#!/usr/bin/env python3
"""One-file Arb third-chart graph/Picard certificate generator v0.9.26.

Embeds the validated v0.9.25 standalone generator, switches the frozen
repository-native Arb proof routine to the certified third centre/frame, and
then reruns the complex fibre-graph, pullback-metric, normalization and Picard
gates. No other local Python file is required.
"""
from __future__ import annotations

import argparse
import base64
import gzip
import hashlib
import importlib.util
import json
import platform
import sys
import time
from pathlib import Path
from typing import Any

VERSION = "0.9.26"
TITLE = "GEOMETRIC-FLOW FORMAL THIRD LOCAL FIBRE-GRAPH / PICARD MICROSTEP"
EMBEDDED_V0925_SHA256 = "a94ba1ab6b5161037b1db0e0d7681487d638ec02e6a78a51739dff9b7935305d"
EMBEDDED_V0925_GZIP_B64 = ""


THIRD_CHART_SWITCH = r'''

    # v0.9.26: every subsequent graph/metric/Picard operation is recomputed
    # at the Arb-certified v0.9.25 third centre in its new frame.
    if not v0925_frame_pass:
        raise ArithmeticError("v0.9.26 refuses an uncertified third frame")
    base_phases=v0925_theta_b
    whitener=v0925_B
    normal=v0925_n
    tangent=v0925_t
    jacobian0=v0925_jac_b
    _v0926_jtmp,gradient0=response_jacobian_and_gradient(base_phases,True)
    jw0=v093_matmul(whitener,jacobian0)
    fb0=v093_matmul(jw0,normal)
    fb_inverse=v093_midpoint_inverse(fb0,"v0.9.26 third-centre normal derivative")
'''


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def sha256_json(value: Any) -> str:
    raw = json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()
    return hashlib.sha256(raw).hexdigest()


def atomic_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n", encoding="utf-8")
    temporary.replace(path)


def materialize_v0925(path: Path) -> Path:
    path.parent.mkdir(parents=True, exist_ok=True)
    raw = gzip.decompress(base64.b64decode(EMBEDDED_V0925_GZIP_B64))
    if hashlib.sha256(raw).hexdigest() != EMBEDDED_V0925_SHA256:
        raise RuntimeError("embedded v0.9.25 source hash mismatch")
    path.write_bytes(raw)
    return path.resolve()


def load_v0925(path: Path):
    spec = importlib.util.spec_from_file_location("embedded_geometric_flow_v0925", path)
    if spec is None or spec.loader is None:
        raise RuntimeError("cannot load embedded v0.9.25")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def parse() -> tuple[argparse.Namespace, list[str]]:
    parser = argparse.ArgumentParser()
    parser.add_argument("--outdir", default="response_fibre_third_picard_v0_9_26_results")
    parser.add_argument("--root-radius", default="2e-18")
    parser.add_argument("--new-domain-radius", default="1e-11")
    return parser.parse_known_args()


def run(args: argparse.Namespace) -> dict[str, Any]:
    started = time.time()
    out = Path(args.outdir).resolve()
    out.mkdir(parents=True, exist_ok=True)
    embedded = materialize_v0925(out / "embedded_sources" / "response_fibre_third_frame_backend_v0_9_25_standalone.py")
    v0925 = load_v0925(embedded)

    # Insert the switch after the v0.9.25 frame certificate is constructed and
    # before the frozen graph/Picard code starts. This causes actual Arb
    # recomputation at the third centre rather than reuse of second-chart data.
    v0925.THIRD_FRAME_ARB_CODE = v0925.THIRD_FRAME_ARB_CODE + THIRD_CHART_SWITCH
    original_patch_driver = v0925.patch_driver

    def patched_driver(source: Path, destination: Path) -> None:
        original_patch_driver(source, destination)
        text = destination.read_text(encoding="utf-8")
        old = '"v0922_signed_field_export_coordinate_system": "v0.9.10-recentered-second-chart-intrinsic-tangent",'
        new = '"v0922_signed_field_export_coordinate_system": "v0.9.26-third-recentered-intrinsic-tangent",'
        if text.count(old) != 1:
            raise RuntimeError("third-chart coordinate-label hook is not unique")
        destination.write_text(text.replace(old, new, 1), encoding="utf-8")

    v0925.patch_driver = patched_driver
    inner_args = argparse.Namespace(
        outdir=str(out / "v0925_third_chart_chain"),
        v0923=None,
        root_radius=str(args.root_radius),
        new_domain_radius=str(args.new_domain_radius),
    )
    frame_summary = v0925.run(inner_args)
    if frame_summary.get("all_scientific_gates_pass") is not True:
        raise RuntimeError("embedded v0.9.25 third-frame gates did not pass")

    candidates = list((out / "v0925_third_chart_chain").rglob("intrinsic_picard_microstep_certificate.json"))
    selected: tuple[Path, dict[str, Any]] | None = None
    for path in candidates:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if data.get("v0922_signed_field_export_coordinate_system") == "v0.9.26-third-recentered-intrinsic-tangent":
            if selected is not None:
                raise RuntimeError("multiple third-chart Picard certificates found")
            selected = (path, data)
    if selected is None:
        raise RuntimeError("third-chart Arb Picard certificate was not emitted")
    picard_path, picard = selected

    required_picard_gates = [
        "complex_parametric_fibre_graph",
        "implicit_graph_derivative_enclosed",
        "pullback_metric_positive_definite",
        "analytic_normalization_branch",
        "intrinsic_projected_gradient_nonstationary",
        "cauchy_lipschitz_resolved",
        "picard_contraction",
        "picard_self_mapping",
        "exact_response_preservation",
        "uniform_strict_L6_descent",
    ]
    pg = picard.get("gates", {})
    gates = {
        "embedded_v0925_hash_exact": sha256_file(embedded) == EMBEDDED_V0925_SHA256,
        "v0925_third_frame_certified": frame_summary.get("third_tangent_normal_frame_certified") is True,
        "formal_interval_arithmetic": picard.get("formal_interval_arithmetic") is True,
        "formal_precision_at_least_192_bits": int(picard.get("arb_precision_bits", 0)) >= 192,
        "third_complex_parametric_fibre_graph": pg.get("complex_parametric_fibre_graph") is True,
        "third_implicit_graph_derivative": pg.get("implicit_graph_derivative_enclosed") is True,
        "third_pullback_metric_positive": pg.get("pullback_metric_positive_definite") is True,
        "third_analytic_normalization_branch": pg.get("analytic_normalization_branch") is True,
        "third_picard_contraction": pg.get("picard_contraction") is True,
        "third_picard_self_mapping": pg.get("picard_self_mapping") is True,
        "third_exact_response_preservation": pg.get("exact_response_preservation") is True,
        "third_uniform_strict_L6_descent": pg.get("uniform_strict_L6_descent") is True,
        "all_repository_native_picard_gates": all(pg.get(k) is True for k in required_picard_gates),
        "validated_ode_claimed_by_backend": picard.get("validated_ODE_claimed") is True,
    }
    passed = all(gates.values())
    certificate = {
        "schema": "geometric-flow/third-local-fibre-picard/v0.9.26",
        "generator_version": VERSION,
        "embedded_v0925_sha256": EMBEDDED_V0925_SHA256,
        "third_frame_certificate_sha256": frame_summary.get("certificate_sha256"),
        "repository_native_picard_certificate_sha256": sha256_file(picard_path),
        "coordinate_system": "v0.9.26-third-recentered-intrinsic-tangent",
        "formal_backend": "python-flint/Arb 192-bit",
        "picard_metrics": {k: picard.get(k) for k in [
            "outer_complex_tangent_radius", "inner_real_picard_radius",
            "refined_normal_graph_radius", "complex_graph_normal_derivative_defect_upper",
            "complex_graph_krawczyk_utilization", "implicit_derivative_neumann_defect_upper",
            "pullback_metric_neumann_defect_upper", "intrinsic_field_sup_norm_upper",
            "intrinsic_projected_gradient_norm_lower", "cauchy_lipschitz_upper",
            "picard_contraction_factor", "picard_displacement_upper",
            "picard_self_mapping_utilization", "uniform_dL6_dt_upper",
        ]},
        "gates": gates,
        "all_scientific_gates_pass": passed,
        "third_local_picard_chart_certified": passed,
        "claim_boundary": "one third-centre complex fibre graph and one validated Picard microstep only; no complete-child, atlas-wide, or global-flow theorem",
    }
    certificate_path = out / "third_local_picard_arb_certificate.json"
    atomic_json(certificate_path, certificate)
    result = {
        "title": TITLE,
        "version": VERSION,
        "scientific_status": (
            "VALIDATED_THIRD_LOCAL_FIBRE_GRAPH_AND_PICARD_MICROSTEP_CERTIFIED"
            if passed else "THIRD_LOCAL_PICARD_INCONCLUSIVE_FAIL_CLOSED"
        ),
        "repository": v0925.REPOSITORY,
        "frozen_commit": v0925.FROZEN_COMMIT,
        "formal_backend": "python-flint/Arb 192-bit",
        "certificate": str(certificate_path),
        "certificate_sha256": sha256_file(certificate_path),
        "repository_native_picard_certificate": str(picard_path),
        "picard_metrics": certificate["picard_metrics"],
        "gates": gates,
        "all_scientific_gates_pass": passed,
        "third_tangent_normal_frame_certified": frame_summary.get("third_tangent_normal_frame_certified") is True,
        "third_local_picard_chart_certified": passed,
        "complete_child_certified": False,
        "ten_chart_continuation_certified": False,
        "global_flow_claimed": False,
        "next_required_step": (
            "chain finite endpoint inclusions inside the third chart and determine its certified uniform-domain exhaustion"
            if passed else "inspect the first failed third graph/metric/Picard gate; do not claim a third local chart"
        ),
        "claim_boundary": certificate["claim_boundary"],
        "elapsed_seconds": time.time() - started,
        "environment": {"python": platform.python_version(), "platform": platform.platform()},
    }
    result["report_sha256_before_self_field"] = sha256_json(result)
    atomic_json(out / "run_summary.json", result)
    return result


def main() -> int:
    args, ignored = parse()
    if ignored:
        print(f"[notice] ignored notebook/kernel arguments: {ignored}")
    try:
        result = run(args)
        print("=" * 112)
        print(f"{TITLE} v{VERSION}")
        print("=" * 112)
        print(json.dumps(result, indent=2, allow_nan=False))
        return 0 if result["all_scientific_gates_pass"] else 2
    except Exception as exc:
        print(json.dumps({
            "scientific_status": "V0926_FAILED_CLOSED",
            "error_type": type(exc).__name__,
            "error": str(exc),
        }, indent=2))
        return 2


if __name__ == "__main__":
    code = main()
    if "ipykernel" not in sys.modules and "google.colab" not in sys.modules:
        raise SystemExit(code)
